# Surah Al-Baqarah (chapter 2) — part 19: ayat 181-190 (IDs 188-197)
SURAH = 2

ENTRIES = {
188: (
"پھر جو کوئی وصیت کو بدلے اس کے (وصیت کے) سن لینے (کے بعد) — تو اس کا گناہ انہی (تبدیل کرنے والوں) پر ہے جو اسے بدلتے ہیں — بے شک اللہ سننے والا، جاننے والا ہے۔",
"""۱۔ وصیت کی اہانت اور تبدیلی پر سخت تنبیہ بیان ہو رہی ہے۔
۲۔ ’’فَمَن بَدَّلَهُ بَعْدَمَا سَمِعَهُ‘‘ — پھر جو کوئی وصیت کو بدلے اس کے (وصیت کے) سن لینے (کے بعد) — یعنی جان بوجھ کر وصیت میں تبدیلی۔
۳۔ ’’فَإِنَّمَا إِثْمُهُ عَلَى الَّذِينَ يُبَدِّلُونَهُ‘‘ — تو اس کا گناہ انہی (تبدیل کرنے والوں) پر ہے جو اسے بدلتے ہیں — یعنی وصیت بدلنے کا بوجھ مرتکبین پر اڑ جاتا ہے۔
۴۔ ’’إِنَّ اللّٰہَ سَمِيعٌ عَلِيمٌ‘‘ — بے شک اللہ سننے والا، جاننے والا ہے — یعنی کوئی چھپانے کی کوشش اللہ سے پوشیدہ نہیں۔
۵۔ عملی سبق: کسی بھی وصیت کی شرافت کو محفوظ رکھیں؛ وصیت گواہوں کے سامنے صاف لکھیں اور اس کی پابندی کریں۔"""
),
189: (
"پھر جو کوئی ڈرے کسی وصیت کرنے والے کی طرف سے ناانصافی یا گناہ (وصیت میں) سے — اور میل کرے ان کے درمیان — تو اس پر کوئی گناہ نہیں — بے شک اللہ بخشنے والا، رحم والا ہے۔",
"""۱۔ وصیت میں ناانصافی کا سدِ باب — اگر وصیت ظالمانہ ہو تو اس کی اصلاح جائز ہے۔
۲۔ ’’فَمَنْ خَافَ مِن مُّوصٍ جَنَفًا أَوْ إِثْمًا‘‘ — پھر جو کوئی ڈرے کسی وصیت کرنے والے کی طرف سے ناانصافی یا گناہ (وصیت میں) سے — یعنی وصیت میں جانبداری یا غلط حکم۔
۳۔ ’’فَأَصْلَحَ بَيْنَهُمْ فَلَا إِثْمَ عَلَيْهِ‘‘ — اور میل کرے ان کے درمیان — تو اس پر کوئی گناہ نہیں — یعنی ورثاء میں صلح کرانا جائز اور ثواب۔
۴۔ ’’إِنَّ اللّٰہَ غَفُورٌ رَّحِيمٌ‘‘ — بے شک اللہ بخشنے والا، رحم والا ہے۔
۵۔ عملی سبق: وصیت ناانصافی سے بھری ہو تو فوراً اصلاح کی طرف رجوع کریں؛ جھگڑے کے بجائے صلح سب سے بہتر راستہ ہے۔"""
),
190: (
"اے ایمان والو! تم پر روزے فرض کیے گئے جیسا کہ تم سے پہلے لوگوں پر فرض کیے گئے — شاید کہ تم (اللہ سے) ڈرو۔",
"""۱۔ رمضان کے روزے کا فرض بیان ہو رہا ہے — یہ امتِ مسلمہ پر واجب عبادت ہے۔
۲۔ ’’كُتِبَ عَلَيْكُمُ الصِّيَامُ‘‘ — تم پر روزے فرض کیے گئے — یعنی روزہ رکھنا لازمی ہے۔
۳۔ ’’كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ‘‘ — جیسا کہ تم سے پہلے لوگوں پر فرض کیے گئے — یعنی روزہ پہلی امتوں (یہود و نصاریٰ اور دیگر اقوام) میں بھی جاری رہا ہے۔
۴۔ ’’لَعَلَّكُمْ تَتَّقُونَ‘‘ — شاید کہ تم (اللہ سے) ڈرو — یعنی روزے کا مقصد تقویٰ پیدا کرنا ہے — دل کی صفائی اور روحانی تربیت۔
۵۔ روزہ عبادتِ خالص ہے — ریا سے پاک، صرف اللہ کے لیے؛ ایک ماہ کی تربیت پوری سال کے لیے تقویٰ دیتی ہے۔
۶۔ عملی سبق: روزے کو صرف بھوکا رہنے کا نام نہ سمجھیں؛ اس کے اندرونی مقصود — دل کی تطہیر — پر دھیان دیں۔"""
),
191: (
"گنتی کے چند دنوں (کے روزے) — پس جو کوئی تم میں سے بیمار ہو یا سفر میں ہو تو (دوسرے دنوں میں) گنتی پوری کرے — اور جو لوگ اس کی طاقت نہ رکھیں (مستقل کمزوری کی وجہ سے) تو (ان پر) فدیہ ہے ایک مسکین کو کھانا کھلانا — پھر جو کوئی خوشی سے نیکی کرے تو وہ اس کے لیے بہتر ہے — اور تمہارا روزہ رکھنا (خود) تمہارے لیے بہتر ہے اگر تم جانتے ہو۔",
"""۱۔ روزے کی سہولت اور رخصت بیان ہو رہی ہے — اللہ بندوں پر بوجھ نہیں ڈالتا۔
۲۔ ’’أَيَّامًا مَّعْدُودَاتٍ‘‘ — گنتی کے چند دنوں (کے روزے) — یعنی رمضان کے ۳۰ دن (یا ۲۹)۔
۳۔ ’’فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَر‘‘ — پس جو کوئی تم میں سے بیمار ہو یا سفر میں ہو تو (دوسرے دنوں میں) گنتی پوری کرے — یعنی بیماری یا سفر میں روزہ چھوڑنے کی اجازت ہے، بعد میں قضا کریں گے۔
۴۔ ’’وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ‘‘ — اور جو لوگ اس کی طاقت نہ رکھیں (مستقل کمزوری کی وجہ سے) تو (ان پر) فدیہ ہے ایک مسکین کو کھانا کھلانا — یعنی مستقل طور پر روزہ نہ رکھ سکنے والے ایک مسکین کو روزانہ کھانا دیں۔
۵۔ ’’فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُ‘‘ — پھر جو کوئی خوشی سے نیکی کرے تو وہ اس کے لیے بہتر ہے — یعنی اگر فدیہ سے زیادہ کھانا دیں تو اجر زیادہ۔
۶۔ ’’وَأَن تَصُومُوا خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ‘‘ — اور تمہارا روزہ رکھنا (خود) تمہارے لیے بہتر ہے اگر تم جانتے ہو — یعنی زیادہ سے زیادہ روزہ رکھنے کوشش کریں۔
۷۔ عملی سبق: بیماری اور سفر کے موقع پر شریعت کی رخصت استعمال کریں؛ اجر اور ہمت دونوں میں توازن رکھیں۔"""
),
192: (
"رمضان کا مہینہ (وہ ہے) جس میں قرآن نازل کیا گیا — ہدایت لوگوں کے لیے اور واضح دلیلیں (ہدایت کی) اور فرقان (حق و باطل میں فرق) — تو جو کوئی تم میں سے اس مہینے میں موجود ہو تو اس کے (پورے) روزے رکھے — اور جو بیمار ہو یا سفر میں ہو تو دوسرے دنوں میں شمار پورے کرے — اللہ تمہارے ساتھ آسانی چاہتا ہے اور سختی نہیں چاہتا — اور تاکہ تم مدت پوری کرو اور شاید کہ تم شکر ادا کرو۔",
"""۱۔ رمضان کی فضیلت بیان ہو رہی ہے — یہ قرآن کا نزول کا مہینہ ہے۔
۲۔ ’’شَهْرُ رَمَضَانَ الَّذِي أُنزِلَ فِيهِ الْقُرْآنُ‘‘ — رمضان کا مہینہ (وہ ہے) جس میں قرآن نازل کیا گیا — یعنی قرآن کی آخری تنزیل اسی مہینے (لَیلۃُ القَدر) میں ہوئی۔
۳۔ ’’هُدًى لِّلنَّاسِ وَبَيِّنَاتٍ مِّنَ الْهُدَىٰ وَالْفُرْقَانِ‘‘ — ہدایت لوگوں کے لیے اور واضح دلیلیں (ہدایت کی) اور فرقان (حق و باطل میں فرق) — یعنی قرآن ہدایت، دلیل اور فرقان — تینوں صفتیں اپنے اندر رکھتا ہے۔
۴۔ ’’فَمَن شَهِدَ مِنكُمُ الشَّهْرَ فَلْيَصُمْهُ‘‘ — تو جو کوئی تم میں سے اس مہینے میں موجود ہو تو اس کے (پورے) روزے رکھے — یعنی رمضان میں موجود ہو تو روزہ لازم ہے۔
۵۔ ’’يُرِيدُ اللّٰہُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْر‘‘ — اللہ تمہارے ساتھ آسانی چاہتا ہے اور سختی نہیں چاہتا — یعنی شریعت کا مقصد بندوں پر آسانی پیدا کرنا ہے۔
۶۔ ’’وَلِتُكْمِلُوا الْعِدَّةَ وَلِتُكَبِّرُوا اللّٰہَ عَلَىٰ مَا هَدَاكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ‘‘ — اور تاکہ تم مدت پوری کرو اور شاید کہ تم شکر ادا کرو — یعنی روزے کی عبادت اسی لیے فرض ہے کہ رمضان کی تعریف اور اللہ کا شکر ادا ہو۔
۷۔ عملی سبق: رمضان میں قرآن کی تلاوت اور فہم کی طرف خصوصی توجہ دیں؛ آسانی کے شریعت کے اصول کو ذہن میں رکھیں۔"""
),
193: (
"اور جب آپ سے میرے بندے میرے بارے میں پوچھیں تو (کہیے) بے شک میں قریب ہوں — دعا کرنے والے کی دعا قبول کرتا ہوں جب وہ مجھے پکارے — پس وہ لوگ میری دعوت قبول کریں اور مجھ پر ایمان رکھیں — شاید کہ وہ ہدایت پائیں۔",
"""۱۔ اللہ اپنی قربت اور دعا کی قبولیت کا اعلان فرما رہا ہے — یہ آیت ایمان والوں کے لیے سب سے بڑی خوشخبری ہے۔
۲۔ ’’وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ‘‘ — اور جب آپ سے میرے بندے میرے بارے میں پوچھیں تو (کہیے) بے شک میں قریب ہوں — یعنی اللہ بندوں سے قریب ہے، بیچ میں کوئی حاجب نہیں۔
۳۔ ’’أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ‘‘ — دعا کرنے والے کی دعا قبول کرتا ہوں جب وہ مجھے پکارے — یعنی دعا کی قبولیت اللہ کا وعدہ ہے۔
۴۔ ’’فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ‘‘ — پس وہ لوگ میری دعوت قبول کریں اور مجھ پر ایمان رکھیں — شاید کہ وہ ہدایت پائیں — یعنی اللہ کی دعوت پر لبیک کہنا اور ایمان قائم رکھنا ہدایت تک کا راستہ ہے۔
۵۔ یہ آیت رمضان میں نازل ہوئی — روزے کی حالت میں دعا کی قبولیت کا یقین بڑھ جاتا ہے۔
۶۔ عملی سبق: ہر لمحہ دعا کرو — اللہ سب ہاجرتوں کے قریب ہے؛ خلوص سے پکارو، جواب ضرور ملے گا۔"""
),
194: (
"تمہارے لیے روزے کی راتوں میں اپنی بیویوں کے پاس جانا حلال کیا گیا ہے — وہ تمہارے لیے لباس ہیں اور تم ان کے لیے لباس ہو — اللہ جانتا ہے کہ تم اپنے آپ سے دھوکا کرتے تھے — پس اس نے تمہاری توبہ قبول کی اور تمہیں معاف کر دیا — پس اب ان سے تعلق رکھو اور اللہ نے جو تمہارے لیے لکھا ہے وہ طلب کرو — اور کھاؤ پیو یہاں تک کہ صبح (کی سفید دھاری) تمہیں (رات کی) سیاہ دھاری سے (نمایاں) ہو جائے — پھر رات تک روزے پورے کرو — اور ان سے متعلق نہ ہو جب تم مسجدوں میں اعتکاف کر رہے ہو — یہ اللہ کی حدود ہیں پس ان کے قریب نہ جاؤ — اسی طرح اللہ اپنی آیات لوگوں کے لیے بیان کرتا ہے — شاید کہ وہ (اللہ سے) ڈریں۔",
"""۱۔ رمضان کی راتوں کے احکام بیان ہو رہے ہیں — بیویوں سے تعلق اور سحری۔
۲۔ ’’أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَىٰ نِسَائِكُمْ‘‘ — تمہارے لیے روزے کی راتوں میں اپنی بیویوں کے پاس جانا حلال کیا گیا ہے — یعنی شروع میں پوری رمضان (دن اور رات دونوں) میں تعلق منع تھا؛ بعد میں صرف دن تک محدود رہا۔
۳۔ ’’هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ‘‘ — وہ تمہارے لیے لباس ہیں اور تم ان کے لیے لباس ہو — یعنی میاں بیوی کا تعلق ایک دوسرے کی حفاظت اور راحت کا سبب ہے۔
۴۔ ’’عَلِمَ اللّٰہُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ‘‘ — اللہ جانتا ہے کہ تم اپنے آپ سے دھوکا کرتے تھے — پس اس نے تمہاری توبہ قبول کی اور تمہیں معاف کر دیا — یعنی وہ شروع والا پابندی زیادہ سخت تھی اس لیے اللہ نے اسے ختم کر دیا۔
۵۔ ’’فَالْآنَ بَاشِرُوهُنَّ وَابْتَغُوا مَا كَتَبَ اللّٰہُ لَكُمْ‘‘ — پس اب ان سے تعلق رکھو اور اللہ نے جو تمہارے لیے لکھا ہے وہ طلب کرو — یعنی روزے کی رات میں تعلق جائز ہے۔
۶۔ ’’وَكُلُوا وَاشْرَبُوا حَتَّىٰ يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ‘‘ — اور کھاؤ پیو یہاں تک کہ صبح (کی سفید دھاری) تمہیں (رات کی) سیاہ دھاری سے (نمایاں) ہو جائے — یعنی سحری کا وقت فجر کی سفیدی تک ہے۔
۷۔ ’’ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ‘‘ — پھر رات تک روزے پورے کرو — یعنی افطار غروبِ آفتاب تک۔
۸۔ ’’وَلَا تُبَاشِرُوهُنَّ وَأَنتُمْ عَاكِفُونَ فِي الْمَسَاجِدِ‘‘ — اور ان سے متعلق نہ ہو جب تم مسجدوں میں اعتکاف کر رہے ہو — یعنی اعتکاف میں بیوی سے تعلق ممنوع ہے۔
۹۔ ’’تِلْكَ حُدُودُ اللّٰہِ فَلَا تَقْرَبُوهَا‘‘ — یہ اللہ کی حدود ہیں پس ان کے قریب نہ جاؤ — یعنی حدود توڑنے سے بچو۔
۱۰۔ عملی سبق: روزے کے احکام ٹھیک طرح سمجھ کر عمل کریں؛ شریعت کی حدود کو ہلکے نہ لیں۔"""
),
195: (
"اور اپنے مال ایک دوسرے کے درمیان ناجائز طریقے سے نہ کھاؤ — (نہ ہی) انہیں حکمرانوں تک پہنچاؤ تاکہ (تم) ان کا کچھ حصہ ظلم سے کھا جاؤ جبکہ تم جانتے ہو۔",
"""۱۔ مال کی ناجائز تقسیم اور رشوت پر تنبیہ — یہ آیت لین دین کے تمام پہلوؤں پر چڑھتی ہے۔
۲۔ ’’وَلَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ‘‘ — اور اپنے مال ایک دوسرے کے درمیان ناجائز طریقے سے نہ کھاؤ — یعنی دھوکہ، چوری، رشوت، سود، قمار — ہر قسم کا ناجائز لین دین حرام ہے۔
۳۔ ’’وَتُدْلُوا بِهَا إِلَى الْحُكَّامِ لِتَأْكُلُوا فَرِيقًا مِّنْ أَمْوَالِ النَّاسِ بِالْإِثْمِ وَأَنتُمْ تَعْلَمُونَ‘‘ — (نہ ہی) انہیں حکمرانوں تک پہنچاؤ تاکہ (تم) ان کا کچھ حصہ ظلم سے کھا جاؤ جبکہ تم جانتے ہو — یعنی حاکم کو رشوت دے کر دوسرے کا حق حاصل کرنا — یہ بدترین قسم کا گناہ ہے۔
۴۔ یہاں رشوت اور اقربا پروری کا واضح منع ہے — جو بھی ناجائز ذریعہ ہو۔
۵۔ عملی سبق: اپنی کمائی میں حلال کا خیال رکھیں؛ کسی کے مال کی طرف ہاتھ نہ بڑھاؤ۔"""
),
196: (
"آپ سے چاند کے بارے میں پوچھا جاتا ہے — کہہ دیجیے: وہ لوگوں کے لیے اور حج کے لیے (وقت) ہیں — اور نیکی یہ نہیں کہ تم گھروں (کے دوران) ان کی پیٹھ سے داخل ہو — بلکہ نیکی یہ ہے کہ (شخص) ڈرو (اللہ سے) — اور گھروں میں داخل ہو ان کے دروازوں سے — اور اللہ سے ڈرو تاکہ تم کامیاب ہو۔",
"""۱۔ نئے چاند کی حقیقت — یہ لوگوں اور حج کے لیے وقت جاننے کا ذریعہ ہے۔
۲۔ ’’يَسْأَلُونَكَ عَنِ الْأَهِلَّةِ‘‘ — آپ سے چاند کے بارے میں پوچھا جاتا ہے — یعنی چاند کی گردش اور مراحل کے بارے میں۔
۳۔ ’’قُلْ هِيَ مَوَاقِيتُ لِلنَّاسِ وَالْحَجِّ‘‘ — کہہ دیجیے: وہ لوگوں کے لیے اور حج کے لیے (وقت) ہیں — یعنی چاند کے مراحل (مہینے) حیض، حمل، حج اور معاملات کے لیے وقت کے پیمانے ہیں۔
۴۔ ’’وَلَيْسَ الْبِرُّ بِأَن تَأْتُوا الْبُيُوتَ مِن ظُهُورِهَا‘‘ — اور نیکی یہ نہیں کہ تم گھروں (کے دوران) ان کی پیٹھ سے داخل ہو — یعنی صرف الفاظ اور ظاہری عمل سے نیکی نہیں بنتی۔
۵۔ ’’وَلَٰكِنَّ الْبِرَّ مَنِ اتَّقَىٰ‘‘ — بلکہ نیکی یہ ہے کہ (شخص) ڈرو (اللہ سے) — یعنی تقویٰ ہی نیکی کی اصل ہے۔
۶۔ ’’وَأْتُوا الْبُيُوتَ مِنْ أَبْوَابِهَا‘‘ — اور گھروں میں داخل ہو ان کے دروازوں سے — یعنی صحیح طریقہ سے کام کرو؛ حق کی راہ سے چلو۔
۷۔ ’’وَاتَّقُوا اللّٰہَ لَعَلَّكُمْ تُفْلِحُونَ‘‘ — اور اللہ سے ڈرو تاکہ تم کامیاب ہو۔
۸۔ عملی سبق: ہر کام میں شرعی اور مناسب راستہ اختیار کریں؛ صحیح راہ سے چلنا ہی کامیابی کی ضمانت ہے۔"""
),
197: (
"اور اللہ کی راہ میں ان لوگوں سے جنگ کرو جو تم سے جنگ کریں — اور زیادتی نہ کرو — بے شک اللہ زیادتی کرنے والوں کو پسند نہیں کرتا۔",
"""۱۔ اللہ کی راہ میں قتال (جنگ) کا حکم — مگر دفاعی حد میں۔
۲۔ ’’وَقَاتِلُوا فِي سَبِيلِ اللّٰہِ الَّذِينَ يُقَاتِلُونَكُمْ‘‘ — اور اللہ کی راہ میں ان لوگوں سے جنگ کرو جو تم سے جنگ کریں — یعنی جارحیت کے خلاف دفاع۔
۳۔ ’’وَلَا تَعْتَدُوا‘‘ — اور زیادتی نہ کرو — یعنی جنگ میں بھی حد سے نہ بڑھو؛ عورتوں، بچوں، بوڑھوں اور بے گناہ پر حملہ ممنوع ہے۔
۴۔ ’’إِنَّ اللّٰہَ لَا يُحِبُّ الْمُعْتَدِينَ‘‘ — بے شک اللہ زیادتی کرنے والوں کو پسند نہیں کرتا — یعنی اللہ جارح کو پسند نہیں کرتا۔
۵۔ یہ آیت جنگ کے ایک بنیادی اصول کو بیان کرتی ہے — اسلام دفاعی ہے، جارحیت نہیں۔
۶۔ عملی سبق: جابرانہ قوتوں کے مقابلے میں دفاع کرنا جائز ہے؛ مگر مظلوموں پر زیادتی ہرگز نہ کرو۔"""
),
}
